WITH base AS (SELECT * FROM order_items WHERE order_id IN (15, 28, 29)), Summary AS (SELECT product_id, CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, COUNT(*) AS total_count FROM base GROUP BY product_id, CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END) SELECT product_id, quantity_bucket, total_count FROM Summary WHERE total_count < 7 ORDER BY product_id
